import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position and transforms
  const scenePos = config.scenePosition || {};
  group.position.set(
    scenePos.x ?? 0,
    scenePos.y ?? 0,
    scenePos.z ?? 0
  );

  if (scenePos.rotationXYZ) {
    group.rotation.order = 'XYZ';
    group.rotation.set(
      scenePos.rotationXYZ[0] ?? 0,
      scenePos.rotationXYZ[1] ?? 0,
      scenePos.rotationXYZ[2] ?? 0
    );
  }

  if (scenePos.scaleXYZ) {
    group.scale.set(
      scenePos.scaleXYZ[0] ?? 1,
      scenePos.scaleXYZ[1] ?? 1,
      scenePos.scaleXYZ[2] ?? 1
    );
  }

  // Create plane geometry with 512:320 atlas aspect ratio
  const width = 2.56;
  const height = 1.6;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load brushed-metal texture
  const texture = ctx.textureLoader.load(
    config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png'
  );

  // Create material with machined-metal PBR per design tokens
  const material = new THREE.MeshStandardNodeMaterial({
    map: texture,
    metalness: 0.5,           // ≤ 0.55
    roughness: 0.6,           // ≥ 0.5
    clearcoat: 0.2,           // ≤ 0.25
    clearcoatRoughness: 0.3,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Setup cleanup function
  group.userData.cleanup = function() {
    geometry.dispose();
    material.dispose();
    if (texture && typeof texture.dispose === 'function') {
      texture.dispose();
    }
    gsap.killTweensOf(group);
  };

  // Initialize event handlers (empty for static card)
  group.userData.handlers = {};

  return group;
}
